SELECT wt.id AS wallet_id, wt.symbol, wt.execution_reason, wt.executed_at, s1.id AS s1_id, s1.generated_at AS g1, s5.id AS s5_id, s5.generated_at AS g5, s5.decision AS d5_same_close, TIMESTAMPDIFF(MICROSECOND, s1.generated_at, s5.generated_at) AS g5_minus_g1_us, pp.id AS position_id, pp.realized_pnl, pp.close_reason FROM crypto_ai.wallet_trade wt JOIN crypto_ai.trade_signal s1 ON s1.id = wt.signal_id AND s1.interval_code = '1m' LEFT JOIN crypto_ai.trade_signal s5 ON s5.symbol = s1.symbol AND s5.interval_code = '5m' AND s5.candle_open_time = DATE_SUB(DATE_ADD(s1.candle_open_time, INTERVAL 1 MINUTE), INTERVAL 5 MINUTE) LEFT JOIN crypto_ai.paper_position pp ON pp.signal_id = s1.id WHERE wt.side = 'BUY' AND wt.executed_at >= '2026-10-01 00:00:00' AND MOD(MINUTE(s1.candle_open_time), 5) = 4 ORDER BY wt.executed_at LIMIT 300;